package com.example.starter.domain;

import java.math.BigDecimal;

/**
 * 发射机合成台账。
 *
 * @param id           主键
 * @param code         发射机编号
 * @param frequencyMhz 发射频率，单位 MHz
 * @param fullPowerW   额定满功率，单位 W
 */
public record Transmitter(long id, String code, BigDecimal frequencyMhz, int fullPowerW) {
}

package com.example.starter.domain;

import java.math.BigDecimal;
import java.time.LocalDateTime;

/**
 * 干扰投诉登记。
 *
 * @param id                主键
 * @param requestId         幂等键
 * @param stationCode       监测站编号
 * @param frequencyMhz      实测频率，单位 MHz
 * @param sampledAt         采样时刻（UTC）
 * @param fieldStrengthDbuv 实测场强，单位 dBuV
 * @param evidenceId        合成证据标识
 * @param fingerprint       全部业务字段指纹
 * @param triggeredEventId  本投诉触发的干扰事件主键；null=未触发
 * @param createdAt         登记时刻（UTC）
 */
public record Complaint(long id, String requestId, String stationCode, BigDecimal frequencyMhz,
                        LocalDateTime sampledAt, BigDecimal fieldStrengthDbuv, String evidenceId,
                        String fingerprint, Long triggeredEventId, LocalDateTime createdAt) {
}

package com.example.starter.domain;

import java.math.BigDecimal;
import java.time.LocalDateTime;

/**
 * 干扰事件。
 *
 * @param id                    主键
 * @param frequencyMhz          受扰频率，单位 MHz
 * @param transmitterId         关联发射机主键
 * @param status                状态：OPEN/CONFIRMED/CLOSED
 * @param conclusion            初查结论：CONFIRMED/CLEARED；null=未初查
 * @param confirmedLimitW       确认时限值快照，单位 W；null=未确认
 * @param triggerComplaintId    触发投诉主键
 * @param createdAt             创建时刻（UTC）
 * @param concludedAt           初查时刻（UTC）；null=未初查
 * @param closedAt              结案时刻（UTC）；null=未结案
 * @param investigateRequestId  初查幂等键；null=未初查
 * @param investigateFingerprint 初查请求指纹
 */
public record InterferenceEvent(long id, BigDecimal frequencyMhz, long transmitterId, String status,
                                String conclusion, Integer confirmedLimitW, long triggerComplaintId,
                                LocalDateTime createdAt, LocalDateTime concludedAt, LocalDateTime closedAt,
                                String investigateRequestId, String investigateFingerprint) {

    public static final String STATUS_OPEN = "OPEN";
    public static final String STATUS_CONFIRMED = "CONFIRMED";
    public static final String STATUS_CLOSED = "CLOSED";

    public static final String CONCLUSION_CONFIRMED = "CONFIRMED";
    public static final String CONCLUSION_CLEARED = "CLEARED";
}

package com.example.starter.domain;

import java.time.LocalDateTime;

/**
 * 限功率指令。
 *
 * @param id                   主键
 * @param transmitterId        目标发射机主键
 * @param status               状态：EXECUTING/LIFTED
 * @param currentLimitW        当前限值，单位 W
 * @param createdAt            创建时刻（UTC）
 * @param liftedAt             解除时刻（UTC）；null=执行中
 * @param liftOpsConfirmer     解除确认人（运行岗）
 * @param liftMonitorConfirmer 解除确认人（监测岗）
 */
public record PowerDirective(long id, long transmitterId, String status, int currentLimitW,
                             LocalDateTime createdAt, LocalDateTime liftedAt,
                             String liftOpsConfirmer, String liftMonitorConfirmer) {

    public static final String STATUS_EXECUTING = "EXECUTING";
    public static final String STATUS_LIFTED = "LIFTED";
}

package com.example.starter.domain;

import java.time.LocalDateTime;

/**
 * 功率指令轨迹，支撑事件与指令全程可复算。
 *
 * @param id          主键
 * @param directiveId 所属指令主键
 * @param eventId     关联事件主键；null=与具体事件无关（如解除）
 * @param changeType  轨迹类型：ISSUE/TIGHTEN/RELAX/LIFT
 * @param limitWAfter 变更后限值，单位 W
 * @param createdAt   变更时刻（UTC）
 * @param note        变更说明
 */
public record DirectiveRevision(long id, long directiveId, Long eventId, String changeType,
                                int limitWAfter, LocalDateTime createdAt, String note) {

    public static final String TYPE_ISSUE = "ISSUE";
    public static final String TYPE_TIGHTEN = "TIGHTEN";
    public static final String TYPE_RELAX = "RELAX";
    public static final String TYPE_LIFT = "LIFT";
}

package com.example.starter.domain;

import java.time.LocalDateTime;

/**
 * 复测记录，与限功率解除同事务原子提交。
 *
 * @param id            主键
 * @param transmitterId 复测发射机主键
 * @param directiveId   关联指令主键
 * @param actualPowerW  实测功率，单位 W
 * @param limitW        复测时执行限值，单位 W
 * @param result        结论：CLEAR=无干扰
 * @param measuredAt    复测采样时刻（UTC）
 * @param recordedBy    记录人
 * @param createdAt     落库时刻（UTC）
 */
public record RetestRecord(long id, long transmitterId, long directiveId, int actualPowerW, int limitW,
                           String result, LocalDateTime measuredAt, String recordedBy, LocalDateTime createdAt) {

    public static final String RESULT_CLEAR = "CLEAR";
}

