public InvestigateResponse investigate(long eventId, InvestigateRequest req) {
    InterferenceEvent e = eventRepo.findById(eventId).orElseThrow(notFound);
    String fp = Fingerprints.of(String.valueOf(eventId), String.valueOf(req.confirmed()), req.note());
    if (e.investigateRequestId() != null) {
